import path from 'node:path';
import fs from 'node:fs/promises';
import {createHash,randomUUID} from 'node:crypto';
import {createFiles} from './files.mjs';
import {generateKrn} from '../plugins/local-generators.mjs';

const fail=(message,status=400)=>Object.assign(new Error(message),{status});
const digest=text=>createHash('sha256').update(text).digest('hex');

// Only the inert subset emitted by vectorNodeSVG is accepted here. This is a
// validation boundary for generated bytes, not a general SVG upload facility.
function validateGeneratedSVG(source){
  const allowed={svg:new Set(['xmlns','width','height','viewBox']),defs:new Set(),path:new Set(['transform','d','fill','fill-rule','stroke','stroke-width']),linearGradient:new Set(['id','x1','y1','x2','y2','gradientUnits']),stop:new Set(['offset','stop-color'])};
  const parent={svg:null,defs:'svg',path:'svg',linearGradient:'defs',stop:'linearGradient'},stack=[],counts={svg:0,defs:0,path:0,linearGradient:0,stop:0};
  const numeric=/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i;
  const numbers=value=>{const values=String(value||'').trim().split(/[\s,]+/);if(!values.length||values.some(s=>!numeric.test(s)||!Number.isFinite(Number(s))||Math.abs(Number(s))>1e7))throw fail('画布 SVG 数值无效');return values.map(Number);};
  const paint=value=>typeof value==='string'&&(/^#[\da-f]{3,8}$/i.test(value)||/^(?:rgba?|hsla?)\([\d\s.,%+-]+\)$/.test(value)||['none','transparent'].includes(value));
  let end=0,match;const tags=/<(\/?)([A-Za-z]+)([^<>]*?)(\/?)>/g;
  while((match=tags.exec(source))){
    if(source.slice(end,match.index).trim())throw fail('画布 SVG 不允许声明、文本或可执行内容');end=tags.lastIndex;
    const [,closing,name,body,selfClosing]=match;
    if(!allowed[name])throw fail('画布 SVG 包含不允许的元素');
    if(closing){if(body.trim()||selfClosing||stack.pop()!==name)throw fail('画布 SVG 标签无效');continue;}
    if(stack.at(-1)!==parent[name]&&!(name==='svg'&&stack.length===0))throw fail('画布 SVG 结构无效');
    counts[name]++;if((name!=='stop'&&counts[name]>1)||(name==='stop'&&counts.stop>32))throw fail('画布 SVG 元素数量无效');
    const attrs={},re=/([\w:-]+)="([^"<>]*)"/g;let attribute,last=0;
    while((attribute=re.exec(body))){if(body.slice(last,attribute.index).trim()||!allowed[name].has(attribute[1])||Object.hasOwn(attrs,attribute[1]))throw fail('画布 SVG 属性无效');last=re.lastIndex;attrs[attribute[1]]=attribute[2];}if(body.slice(last).trim()||Object.keys(attrs).length!==allowed[name].size)throw fail('画布 SVG 属性缺失或无效');
    if(name==='svg'){if(attrs.xmlns!=='http://www.w3.org/2000/svg'||numbers(attrs.width).length!==1||Number(attrs.width)<=0||numbers(attrs.height).length!==1||Number(attrs.height)<=0)throw fail('画布 SVG 尺寸无效');const box=numbers(attrs.viewBox);if(box.length!==4||box[2]<=0||box[3]<=0)throw fail('画布 SVG viewBox 无效');}
    if(name==='path'){
      if(!/^[MLCZ\d.eE+,\s-]*$/.test(attrs.d)||!attrs.d.includes('M')||!['nonzero','evenodd'].includes(attrs['fill-rule'])||!paint(attrs.stroke)||!(paint(attrs.fill)||attrs.fill==='url(#paint)'&&counts.linearGradient===1))throw fail('画布 SVG 路径或填充无效');
      const values=attrs.d.replace(/[MLCZ]/g,' ').trim();if(values)numbers(values);if(numbers(attrs['stroke-width']).length!==1||Number(attrs['stroke-width'])<0)throw fail('画布 SVG 描边无效');
      let position=0;const transforms=/(translate|rotate|scale)\(([^)]*)\)/g;let transform;
      while((transform=transforms.exec(attrs.transform))){if(attrs.transform.slice(position,transform.index).trim())throw fail('画布 SVG 变换无效');position=transforms.lastIndex;const args=numbers(transform[2]);if(args.length!==(transform[1]==='rotate'?1:2))throw fail('画布 SVG 变换参数无效');}if(attrs.transform.slice(position).trim())throw fail('画布 SVG 变换无效');
    }
    if(name==='linearGradient'){if(attrs.id!=='paint'||attrs.gradientUnits!=='objectBoundingBox')throw fail('画布 SVG 渐变引用无效');for(const key of ['x1','y1','x2','y2'])if(numbers(attrs[key]).length!==1)throw fail('画布 SVG 渐变坐标无效');}
    if(name==='stop'&&(!paint(attrs['stop-color'])||numbers(attrs.offset).length!==1||Number(attrs.offset)<0||Number(attrs.offset)>1))throw fail('画布 SVG 色标无效');
    if(!selfClosing)stack.push(name);
  }
  if(end!==source.length||stack.length||counts.svg!==1||counts.defs!==1||counts.path!==1||counts.linearGradient&&counts.stop<2)throw fail('画布 SVG 文档不完整');
}

export function validateCanvasAsset(asset){
  if(!asset||typeof asset.base64!=='string'||!/^[A-Za-z0-9+/]*={0,2}$/.test(asset.base64))throw fail('画布素材编码无效');
  const content=Buffer.from(asset.base64,'base64');
  if(!content.length||content.length>512*1024||content.toString('base64')!==asset.base64)throw fail('画布素材内容无效或超过 512 KB');
  const vector=/^canvas-vector-([a-f0-9]{64})\.svg$/.exec(asset.fileName||'');
  if(vector){
    if(asset.mime!=='image/svg+xml'||digest(content)!==vector[1])throw fail('画布 SVG 类型或内容哈希不匹配');
    let source;try{source=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(content);}catch{throw fail('画布 SVG 必须为有效 UTF-8');}
    validateGeneratedSVG(source);
  }else{
    const raster=/^canvas-image-([a-f0-9]{64})\.(png|jpg|webp)$/.exec(asset.fileName||''),extensions={'image/png':'png','image/jpeg':'jpg','image/webp':'webp'};
    if(!raster||extensions[asset.mime]!==raster[2]||digest(`data:${asset.mime};base64,${asset.base64}`)!==raster[1])throw fail('画布图片类型或哈希无效');
    const isImage=asset.mime==='image/png'?content.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])):asset.mime==='image/jpeg'?content.length>3&&content[0]===255&&content[1]===216&&content[2]===255:content.subarray(0,4).toString()==='RIFF'&&content.subarray(8,12).toString()==='WEBP';
    if(!isImage)throw fail('画布图片内容无效');
  }
  return{path:'assets/'+asset.fileName,content,mime:asset.mime};
}

export function createCanvasService({api,getWorkspace}){
  const locks=new Map(),listeners=new Set();
  const subscribe=listener=>{if(typeof listener!=='function')throw new TypeError('Canvas listener must be a function');listeners.add(listener);return()=>listeners.delete(listener);};
  function publish(context,saved,metadata){
    for(const listener of listeners){try{listener({...context,...saved,metadata});}catch(error){console.warn('Canvas change listener failed:',error.message);}}
  }
  async function target(projectId){
    let project;
    if(projectId!==null&&projectId!==undefined&&projectId!==''){
      project=api.findProject(projectId);if(!project)throw fail('项目不存在',404);
    }
    const workspace=await fs.realpath(project?.projectPath||getWorkspace());
    if(!(await fs.stat(workspace)).isDirectory())throw fail('项目目录不可用',404);
    if(!project)for(const item of api.state.projects){
      // macOS temp paths and user-selected folders may name the same real
      // directory through /var or /tmp aliases. Bind by the actual directory.
      try{if(await fs.realpath(item.projectPath)===workspace){project=item;break;}}catch{}
    }
    return {workspace,projectId:project?.id??null,files:createFiles(workspace)};
  }
  async function lock(key,action){
    const previous=locks.get(key)||Promise.resolve();
    const pending=previous.catch(()=>{}).then(action);locks.set(key,pending);
    try{return await pending;}finally{if(locks.get(key)===pending)locks.delete(key);}
  }
  async function read(context){
    let content;
    try {content=(await context.files.read('canvas.json')).content;}
    catch(error){if(error.code==='ENOENT')return {document:null,revision:null,workspace:context.workspace,workspaceKey:digest(context.workspace),projectId:context.projectId};throw error;}
    const {validateDocument}=await import('../canvas/model.mjs');
    const document=validateDocument(JSON.parse(content));
    return {document,revision:digest(content),workspace:context.workspace,workspaceKey:digest(context.workspace),projectId:context.projectId};
  }
  function compare(body,current){
    if(!Object.hasOwn(body,'expectedRevision'))throw fail('保存画布需要 expectedRevision');
    if(body.expectedRevision!==current.revision)throw fail('画布已被其他窗口或编辑器修改，请重新载入后再保存',409);
  }
  async function saveUnlocked(context,body,metadata={}){
    const current=await read(context);compare(body,current);
    const {validateDocument}=await import('../canvas/model.mjs');
    const document=validateDocument(body.document),content=JSON.stringify(document,null,2)+'\n';
    if(Buffer.byteLength(content)>2*1024*1024)throw fail('画布文档不能超过 2 MB',413);
    // Replace a complete document atomically. Never follow a canvas.json symlink,
    // including a dangling link that could otherwise escape the project.
    const destination=path.join(context.workspace,'canvas.json');
    const temporary=path.join(context.workspace,`.m0-canvas-${randomUUID()}.tmp`);
    const check=async()=>{try{const stat=await fs.lstat(destination);if(stat.isSymbolicLink()||!stat.isFile())throw fail('画布路径需要是项目内的普通文件');}catch(error){if(error.code!=='ENOENT')throw error;}};
    await check();
    try{
      await fs.writeFile(temporary,content,{encoding:'utf8',flag:'wx',mode:0o600});
      await check();
      // External editors don't share our lock: detect edits while validating.
      compare(body,await read(context));
      await fs.rename(temporary,destination);
    }finally{await fs.unlink(temporary).catch(error=>{if(error.code!=='ENOENT')throw error;});}
    const saved={...current,document,revision:digest(content)};
    publish(context,saved,metadata);
    return saved;
  }
  const save=(context,body,metadata={})=>lock(context.workspace,()=>saveUnlocked(context,body,metadata));
  const transact=(context,mutator,metadata={})=>lock(context.workspace,async()=>{
    if(typeof mutator!=='function')throw new TypeError('Canvas transaction requires a mutator');
    const current=await read(context),proposal=await mutator(current);
    if(proposal===undefined||proposal===null)return current;
    return saveUnlocked(context,{document:proposal.document??proposal,expectedRevision:current.revision},metadata);
  });
  async function handle(req,res,url,body={}){
    if(!['/__local/canvas','/__local/canvas/generate'].includes(url.pathname))return false;
    const send=(data,status=200)=>{res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store'});res.end(JSON.stringify(data));return true;};
    const generate=url.pathname.endsWith('/generate');
    if(!((generate&&req.method==='POST')||(!generate&&['GET','PUT'].includes(req.method))))return send({error:'Method not allowed'},405);
    const context=await target(url.searchParams.get('projectId'));
    if(url.searchParams.has('workspaceKey')&&url.searchParams.get('workspaceKey')!==digest(context.workspace))throw fail('当前工作区已切换，请先导出未保存设计，再重新打开画布',409);
    if(!generate&&req.method==='GET')return send(await read(context));
    if(!generate)return send(await save(context,body));
    return lock(context.workspace,async()=>{
      const current=await read(context);
      compare(body,current);
      if(!current.document)throw fail('请先保存画布');
      const directory=body.directory||'';
      if(typeof directory!=='string'||directory.startsWith('/')||directory.split(/[\\/]/).some(item=>item==='..'||item.startsWith('.'))||directory.includes('\0'))throw fail('生成目录应为工作区内的普通相对路径');
      const model=await import('../canvas/model.mjs');
      const {documentToM0Schema}=model;
      const schema=documentToM0Schema(current.document,{nodeId:body.nodeId});
      const assets=typeof model.extractCanvasAssets==='function'?await model.extractCanvasAssets(current.document,{nodeId:body.nodeId}):[];
      const binary=assets.map(validateCanvasAsset);
      const output=await generateKrn(schema);
      // The native editor may change canvas.json while the worker is running.
      if((await read(context)).revision!==current.revision)throw fail('生成期间画布已改变，请保存后重新生成',409);
      const files=output.files.map(file=>({...file,path:directory?directory.replace(/\/$/,'')+'/'+file.path:file.path}));
      const assetFiles=binary.map(file=>({...file,path:directory?directory.replace(/\/$/,'')+'/'+file.path:file.path}));
      const imported=await context.files.importProject([...files,...assetFiles],{allowBinary:true});
      return send({...output,files,assets:assetFiles.map(({path,content,mime})=>({path,size:content.length,mime})),imported,workspace:context.workspace,projectId:context.projectId,revision:current.revision});
    });
  }
  return {handle,target,read,save,transact,subscribe};
}
